import { useEffect, useMemo, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { io } from 'socket.io-client';
import { Car, ChevronRight, Clock3, CreditCard, DoorOpen, LayoutDashboard, LogOut, Menu, Moon, ParkingSquare, ShieldCheck, Sun, UserRound, Users, X, Bell, CalendarDays, BarChart3, Search, CheckCircle2, AlertTriangle, CircleDollarSign, Settings, ArrowRight } from 'lucide-react';
import { AreaChart, Area, ResponsiveContainer, Tooltip, XAxis } from 'recharts';

const INITIAL_SLOTS = ['free','occupied','free','reserved','free','occupied'].map((status, index) => ({ slot_id: index + 1, status, user_name: status === 'occupied' ? ['Rahul Mehta', 'Anita Rao'][index === 1 ? 0 : 1] : null, vehicle_number: status === 'occupied' ? ['MH 12 AB 1104','MH 14 PT 7832'][index === 1 ? 0 : 1] : null, entry_time: new Date(Date.now() - (index + 1) * 270000).toISOString() }));
const NAV = [{ id:'overview', label:'Overview', icon:LayoutDashboard }, { id:'book', label:'Book Slot', icon:CalendarDays }, { id:'payments', label:'Payments', icon:CreditCard }, { id:'sessions', label:'My Sessions', icon:Clock3 }, { id:'bookings', label:'Bookings', icon:ParkingSquare }, { id:'profile', label:'Profile', icon:UserRound }];
const ADMIN_NAV = [{ id:'overview',label:'Live Overview',icon:LayoutDashboard },{ id:'book',label:'Book Slot',icon:CalendarDays },{ id:'payments',label:'Payments',icon:CreditCard },{ id:'slots',label:'Slot Control',icon:ParkingSquare },{ id:'users',label:'Users',icon:Users },{ id:'sessions',label:'Sessions',icon:Clock3 },{ id:'bookings',label:'Bookings',icon:CalendarDays },{ id:'refunds',label:'Refunds',icon:CircleDollarSign },{ id:'analytics',label:'Analytics',icon:BarChart3 },{ id:'settings',label:'Settings',icon:Settings },{ id:'hardware',label:'Hardware',icon:ShieldCheck }];
const formatMoney = (value) => `Rs. ${Number(value || 0).toFixed(0)}`;
const localDateTime = (value = new Date()) => new Date(value.getTime() - value.getTimezoneOffset() * 60_000).toISOString().slice(0, 16);
const API_BASE_URL = String(import.meta.env.VITE_API_URL || '').replace(/\/+$/, '');
const apiUrl = (url) => `${API_BASE_URL}${url}`;
const accessToken = () => sessionStorage.getItem('smartpark_access_token');
const api = async (url, options = {}) => { const token = accessToken(); const response = await fetch(apiUrl(url), { credentials: API_BASE_URL ? 'omit' : 'include', headers: { 'Content-Type':'application/json', ...(token ? { Authorization:`Bearer ${token}` } : {}), ...options.headers }, ...options }); const payload = await response.text(); let body; try { body = payload ? JSON.parse(payload) : {}; } catch { body = { message: payload || `Request failed with status ${response.status}` }; } if (!response.ok) throw new Error(body.message || `Request failed with status ${response.status}`); return body; };
const loadRazorpay = () => new Promise((resolve) => { if (window.Razorpay) return resolve(true); const script = document.createElement('script'); script.src = 'https://checkout.razorpay.com/v1/checkout.js'; script.onload = () => resolve(true); script.onerror = () => resolve(false); document.body.appendChild(script); });

function SlotCard({ slot, selectable, selected, onSelect, admin, onGate }) { const occupied = slot.status === 'occupied'; const elapsed = Number(slot.elapsed_minutes || 0); const duration = `${Math.floor(elapsed / 60)}h ${elapsed % 60}m`; return <motion.button whileHover={{ y:-3 }} onClick={() => selectable && slot.status === 'free' && onSelect(slot)} className={`slot-card ${slot.status} ${selected ? 'selected' : ''} ${selectable && slot.status === 'free' ? 'selectable' : ''}`}><div className="slot-top"><span className="slot-id">{slot.label || `P-${String(slot.slot_id).padStart(2,'0')}`}</span><span className="status-dot"/></div><Car size={30} strokeWidth={1.8}/><strong>{slot.status}</strong><small>{occupied ? slot.user_name || (admin ? 'Vehicle detected' : 'User ***') : slot.status === 'reserved' ? 'Reserved soon' : slot.status === 'maintenance' ? 'Temporarily unavailable' : 'Ready to park'}</small>{occupied && <span className={`slot-time ${slot.is_overtime ? 'overtime' : ''}`}>{duration} · {formatMoney(slot.live_bill || 0)}{slot.is_overtime ? ' · OT' : ''}</span>}{admin && <span onClick={(event) => { event.stopPropagation(); onGate(slot, slot.gate_status === 'open' ? 'close' : 'open'); }} className="gate-button"><DoorOpen size={14}/>{slot.gate_status === 'open' ? 'Close gate' : 'Open gate'}</span>}</motion.button>; }

function SlotMap({ slots, selectable, selected, onSelect, admin, onGate }) { return <div className="slot-grid">{slots.map((slot) => <SlotCard key={slot.slot_id} slot={slot} selectable={selectable} selected={selected?.slot_id === slot.slot_id} onSelect={onSelect} admin={admin} onGate={onGate}/>)}</div>; }
function LiveParkingMap({ slots, admin, onGate }) { const available = slots.filter((slot) => slot.status === 'free').length; return <div className="parking-map" aria-label="Live parking lot map"><div className="map-header"><span><i/> Live socket feed</span><b>{available} spaces available</b></div><div className="map-lot"><div className="map-gate-entry"><DoorOpen size={18}/><span>ENTRY</span></div><div className="map-drive"><span>ONE WAY</span><i>→</i></div><div className="map-spaces">{slots.map((slot) => <motion.div layout key={slot.slot_id} className={`map-space ${slot.status}`}><div><b>P-{String(slot.slot_id).padStart(2, '0')}</b><span className="map-status"><i/>{slot.status}</span></div><Car size={25}/><small>{slot.status === 'occupied' ? (admin ? slot.vehicle_number || 'Vehicle detected' : 'Vehicle parked') : slot.status === 'reserved' ? 'Reserved' : slot.status === 'maintenance' ? 'Unavailable' : 'Ready'}</small></motion.div>)}</div><div className="map-exit"><span>EXIT</span><DoorOpen size={18}/></div></div><div className="map-footer"><div><span><i className="free"/>Available</span><span><i className="occupied"/>Occupied</span><span><i className="reserved"/>Reserved</span><span><i className="maintenance"/>Maintenance</span></div>{admin && <button className="link" onClick={() => onGate({ slot_id: 1, gate_status: 'closed' }, 'open')}>Open entry gate</button>}</div></div>; }
function DemoUpiPayment({ booking, onPay, onCancel, paying }) { return <section className="panel demo-upi-panel"><span className="eyebrow">STEP 3 OF 3 · DEMO PAYMENT</span><h2>Complete your UPI payment.</h2><p>Your slot is held while you complete this demo payment.</p><div className="upi-details"><span>Demo UPI ID</span><b>smartpark@upi</b><span>Amount payable</span><strong>{formatMoney(booking.amount)}</strong><small>Booking #{booking.booking_id} · Slot P-{String(booking.slot_number).padStart(2, '0')}</small></div><div className="upi-note"><CheckCircle2 size={17}/> Demo mode: click Pay now to complete payment instantly.</div><button className="primary full" disabled={paying} onClick={onPay}>{paying ? 'Processing payment…' : `Pay ${formatMoney(booking.amount)} now`} <CreditCard size={18}/></button><button className="link cancel-payment" disabled={paying} onClick={onCancel}>Cancel payment</button></section>; }
function BookingPaymentSuccess({ booking, onDone }) { return <section className="panel booking-confirm booking-success"><CheckCircle2/><span className="eyebrow">PAYMENT SUCCESSFUL</span><h2>Slot P-{String(booking.slot_number).padStart(2,'0')} is reserved.</h2><div className="booking-code">SMARTPARK <b>#{booking.booking_id}</b></div><p><CalendarDays size={17}/> {new Date(booking.expected_arrival).toLocaleString('en-IN')}</p><p><Clock3 size={17}/> {booking.duration_hours} hour(s) · {formatMoney(booking.amount)}</p><p><CreditCard size={17}/> Payment complete · Demo UPI</p><a className="secondary full" href={`/api/booking/${booking.booking_id}/payment-receipt`} target="_blank" rel="noreferrer">Download payment receipt (PDF)</a><button className="primary full" onClick={onDone}>Go to My Bookings</button></section>; }
function AdvanceBookingPanel({ user, slots, setPage }) {
  const [selected, setSelected] = useState(null); const [arrival, setArrival] = useState(() => localDateTime()); const [duration, setDuration] = useState(1); const [fastag, setFastag] = useState(null); const [confirmation, setConfirmation] = useState(null); const [paymentStep, setPaymentStep] = useState(null); const [createdBooking, setCreatedBooking] = useState(null); const [upiPayment, setUpiPayment] = useState(null); const [upiId, setUpiId] = useState(''); const [paying, setPaying] = useState(false); const [message, setMessage] = useState('');
  useEffect(() => { api('/api/fastag/me').then((result) => setFastag(result.data)).catch(() => setFastag(null)); }, []);
  const createBooking = async () => { if (createdBooking) return createdBooking; if (!selected) throw new Error('Select a free parking slot first.'); const result = await api('/api/booking', { method:'POST', body:JSON.stringify({ slotNumber:selected.slot_id, expectedArrival:new Date(arrival).toISOString(), durationHours:Number(duration), vehicleNumber:user.vehicle_number }) }); const booking = { booking_id:result.data.booking_id, slot_number:selected.slot_id, expected_arrival:arrival, duration_hours:Number(duration), amount:20, payment_status:'unpaid' }; setCreatedBooking(booking); return booking; };
  const payFastag = async () => { try { setPaying(true); const booking = await createBooking(); await api(`/api/fastag/pay/booking/${booking.booking_id}`, { method:'POST', body:'{}' }); setCreatedBooking(null); setPaymentStep(null); setConfirmation({...booking, payment_status:'paid'}); } catch (error) { setMessage(error.message); } finally { setPaying(false); } };
  const startUpi = async () => { try { setPaying(true); const booking = await createBooking(); const result = await api(`/api/payment/qr/booking/${booking.booking_id}`, { method:'POST', body:'{}' }); setUpiPayment({...booking, ...result.data}); setPaymentStep('upi'); } catch (error) { setMessage(error.message); } finally { setPaying(false); } };
  const confirmUpi = async () => { if (!/^[a-zA-Z0-9._-]{2,}@[a-zA-Z]{2,}$/.test(upiId)) return setMessage('Enter a valid UPI ID, for example name@upi.'); try { setPaying(true); await api('/api/payment/verify', { method:'POST', body:JSON.stringify({ bookingId:upiPayment.booking_id, amount:20, razorpayPaymentId:`manual_upi_${upiId.replace(/[^a-zA-Z0-9]/g, '_')}_${Date.now()}`, mode:'upi_qr' }) }); setCreatedBooking(null); setPaymentStep(null); setConfirmation({...upiPayment, payment_status:'paid'}); } catch (error) { setMessage(error.message); } finally { setPaying(false); } };
  const cancelUpi = async () => { try { const booking = upiPayment || createdBooking; if (booking) await api(`/api/booking/${booking.booking_id}/cancel`, { method:'PUT' }); setCreatedBooking(null); setUpiPayment(null); setPaymentStep(null); setMessage('Payment cancelled. The slot was not reserved.'); } catch (error) { setMessage(error.message); } };
  if (confirmation) return <BookingPaymentSuccess booking={confirmation} onDone={() => setPage('bookings')}/>;
  return <section className="book-layout"><div className="panel intro-panel"><span className="eyebrow">ONLINE PRE-BOOKING</span><h2>Reserve from one to twelve hours.</h2><p>Every pre-booking requires a mandatory, non-refundable online advance of <b>Rs.20</b> for the first hour. Physical payment is not available for reservations.</p><div className="legend"><span><i className="free"/>Free</span><span><i className="occupied"/>Occupied</span><span><i className="reserved"/>Reserved</span></div></div><div className="panel"><SlotMap slots={slots} selectable={user.status !== 'blocked'} selected={selected} onSelect={setSelected}/></div>{selected && <div className="booking-panel panel"><span className="eyebrow">CONFIRM AND PAY</span><h3>Slot P-{String(selected.slot_id).padStart(2,'0')}</h3><label>Expected arrival<input type="datetime-local" min={localDateTime()} max={localDateTime(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000))} value={arrival} onChange={(event) => setArrival(event.target.value)}/></label><label>Reserved duration <b>{duration} hour{duration > 1 ? 's' : ''}</b><input type="range" min="1" max="12" value={duration} onChange={(event) => setDuration(event.target.value)}/></label><div className="advance-summary"><b>Mandatory non-refundable online advance</b><strong>Rs. 20</strong><span>Covers the first hour. Your selected reservation duration is {duration} hour{duration > 1 ? 's' : ''}.</span></div><button className="primary full" onClick={() => { setMessage(''); setPaymentStep('choice'); }}>Pay Rs. 20 advance online <CreditCard size={18}/></button></div>}{paymentStep && <div className="payment-modal-backdrop"><section className="payment-modal panel"><button className="modal-close" onClick={() => paymentStep === 'upi' ? cancelUpi() : setPaymentStep(null)}><X/></button>{paymentStep === 'choice' ? <><span className="eyebrow">CHOOSE PAYMENT METHOD</span><h2>Pay Rs.20 advance</h2><p>Select a secure online payment option to reserve your slot.</p><button className="payment-method fastag-method" disabled={!fastag || paying} onClick={payFastag}><b>FASTag payment</b><span>{fastag ? `Auto-deduct Rs.20 from wallet · Balance ${formatMoney(fastag.wallet_balance)}` : 'Link an active FASTag in Payments to use this option'}</span></button><button className="payment-method upi-method" disabled={paying} onClick={startUpi}><b>UPI payment</b><span>Scan QR code or enter your UPI ID manually</span></button></> : <><span className="eyebrow">UPI PAYMENT</span><h2>Pay Rs.20 advance</h2><img className="booking-qr" src={upiPayment?.qrDataUrl} alt="UPI QR code for SmartPark booking"/><b>{upiPayment?.upiId}</b><a className="secondary" href={upiPayment?.upiUrl}>Open payment app</a><label>Your UPI ID<input required placeholder="name@upi" value={upiId} onChange={(event) => setUpiId(event.target.value)}/></label><button className="primary full" disabled={paying} onClick={confirmUpi}>{paying ? 'Confirming payment...' : 'Confirm UPI payment'}</button><button className="link" disabled={paying} onClick={cancelUpi}>Cancel payment</button></>}</section></div>}{message && <p className="inline-notice">{message}</p>}</section>;
}
function PhonePeBookingSuccess({ booking, onDone }) { return <section className="panel booking-confirm booking-success"><CheckCircle2/><span className="eyebrow">PAYMENT SUCCESSFUL</span><h2>Slot P-{String(booking.slot_number).padStart(2, '0')} is reserved.</h2><div className="booking-code">SMARTPARK <b>#{booking.booking_id}</b></div><p><CalendarDays size={17}/> {new Date(booking.expected_arrival).toLocaleString('en-IN')}</p><p><Clock3 size={17}/> {booking.duration_hours} hour(s) · {formatMoney(booking.amount)}</p><p><CreditCard size={17}/> Payment complete · PhonePe UPI</p><a className="secondary full" href={`/api/booking/${booking.booking_id}/payment-receipt`} target="_blank" rel="noreferrer">Download payment receipt (PDF)</a><button className="primary full" onClick={onDone}>Go to My Bookings</button></section>; }

function PhonePeAdvanceBookingPanel({ user, slots, setPage }) {
  const [selected, setSelected] = useState(null);
  const [arrival, setArrival] = useState(() => localDateTime());
  const [duration, setDuration] = useState(1);
  const [fastag, setFastag] = useState(null);
  const [confirmation, setConfirmation] = useState(null);
  const [paymentStep, setPaymentStep] = useState(null);
  const [createdBooking, setCreatedBooking] = useState(null);
  const [phonePePayment, setPhonePePayment] = useState(null);
  const [paying, setPaying] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => { api('/api/fastag/me').then((result) => setFastag(result.data)).catch(() => setFastag(null)); }, []);
  useEffect(() => {
    const merchantOrderId = new URLSearchParams(window.location.search).get('phonepeOrder');
    const saved = localStorage.getItem('smartpark_phonepe_payment');
    if (!merchantOrderId || !saved) return;
    try {
      const payment = JSON.parse(saved);
      if (payment.merchantOrderId === merchantOrderId) {
        setCreatedBooking(payment);
        setPhonePePayment(payment);
        setPaymentStep('phonepe');
        window.history.replaceState({}, '', window.location.pathname);
      }
    } catch { localStorage.removeItem('smartpark_phonepe_payment'); }
  }, []);

  const createBooking = async () => {
    if (createdBooking) return createdBooking;
    if (!selected) throw new Error('Select a free parking slot first.');
    const result = await api('/api/booking', { method:'POST', body:JSON.stringify({ slotNumber:selected.slot_id, expectedArrival:new Date(arrival).toISOString(), durationHours:Number(duration), vehicleNumber:user.vehicle_number }) });
    const booking = { booking_id:result.data.booking_id, slot_number:selected.slot_id, expected_arrival:arrival, duration_hours:Number(duration), amount:result.data.amount, payment_status:'unpaid' };
    setCreatedBooking(booking);
    return booking;
  };
  const payFastag = async () => {
    try {
      setPaying(true);
      const booking = await createBooking();
      await api(`/api/fastag/pay/booking/${booking.booking_id}`, { method:'POST', body:'{}' });
      setCreatedBooking(null);
      setPaymentStep(null);
      setConfirmation({ ...booking, payment_status:'paid' });
    } catch (error) { setMessage(error.message); } finally { setPaying(false); }
  };
  const startPhonePe = async () => {
    try {
      setPaying(true);
      const booking = await createBooking();
      const result = await api(`/api/phonepe/booking/${booking.booking_id}/initiate`, { method:'POST', body:'{}' });
      const payment = { ...booking, ...result.data };
      setPhonePePayment(payment);
      setPaymentStep('phonepe');
      localStorage.setItem('smartpark_phonepe_payment', JSON.stringify(payment));
    } catch (error) { setMessage(error.message); } finally { setPaying(false); }
  };
  const checkPhonePeStatus = async () => {
    if (!phonePePayment?.merchantOrderId) return;
    try {
      setPaying(true);
      const result = await api(`/api/phonepe/order/${phonePePayment.merchantOrderId}/status`);
      if (result.data.state === 'COMPLETED') {
        localStorage.removeItem('smartpark_phonepe_payment');
        setCreatedBooking(null);
        setPaymentStep(null);
        setConfirmation({ ...phonePePayment, payment_status:'paid' });
      } else setMessage(`PhonePe payment is ${result.data.state.toLowerCase()}. Complete it on PhonePe, then check again.`);
    } catch (error) { setMessage(error.message); } finally { setPaying(false); }
  };
  useEffect(() => {
    if (paymentStep !== 'phonepe' || !phonePePayment?.merchantOrderId) return undefined;
    const timer = window.setInterval(checkPhonePeStatus, 5000);
    return () => window.clearInterval(timer);
  }, [paymentStep, phonePePayment?.merchantOrderId]);

  if (confirmation) return <PhonePeBookingSuccess booking={confirmation} onDone={() => setPage('bookings')}/>;
  return <section className="book-layout"><div className="panel intro-panel"><span className="eyebrow">ONLINE PRE-BOOKING</span><h2>Reserve from one to twelve hours.</h2><p>Every pre-booking requires a mandatory, non-refundable online advance of <b>Rs.20</b> for the first hour. Physical payment is not available for reservations.</p><div className="legend"><span><i className="free"/>Free</span><span><i className="occupied"/>Occupied</span><span><i className="reserved"/>Reserved</span></div></div><div className="panel"><SlotMap slots={slots} selectable={user.status !== 'blocked'} selected={selected} onSelect={setSelected}/></div>{selected && <div className="booking-panel panel"><span className="eyebrow">CONFIRM AND PAY</span><h3>Slot P-{String(selected.slot_id).padStart(2, '0')}</h3><label>Expected arrival<input type="datetime-local" min={localDateTime()} max={localDateTime(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000))} value={arrival} onChange={(event) => setArrival(event.target.value)}/></label><label>Reserved duration <b>{duration} hour{duration > 1 ? 's' : ''}</b><input type="range" min="1" max="12" value={duration} onChange={(event) => setDuration(event.target.value)}/></label><div className="advance-summary"><b>Mandatory non-refundable online advance</b><strong>Rs. 20</strong><span>Covers the first hour. Your selected reservation duration is {duration} hour{duration > 1 ? 's' : ''}.</span></div><button className="primary full" onClick={() => { setMessage(''); setPaymentStep('choice'); }}>Pay Rs. 20 advance online <CreditCard size={18}/></button></div>}{paymentStep && <div className="payment-modal-backdrop"><section className="payment-modal panel"><button className="modal-close" aria-label="Close payment" onClick={() => setPaymentStep(null)}><X/></button>{paymentStep === 'choice' ? <><span className="eyebrow">CHOOSE PAYMENT METHOD</span><h2>Pay Rs.20 advance</h2><p>Select a secure online payment option to reserve your slot.</p><button className="payment-method fastag-method" disabled={!fastag || paying} onClick={payFastag}><b>FASTag payment</b><span>{fastag ? `Auto-deduct Rs.20 from wallet · Balance ${formatMoney(fastag.wallet_balance)}` : 'Link an active FASTag in Payments to use this option'}</span></button><button className="payment-method upi-method" disabled={paying} onClick={startPhonePe}><b>PhonePe UPI payment</b><span>Secure UAT checkout with UPI QR, UPI ID and installed UPI apps</span></button></> : <><span className="eyebrow">PHONEPE UAT</span><h2>Complete Rs.20 UPI payment</h2><p>PhonePe securely provides the QR scanner, UPI ID, and payment-app choices. SmartPark reserves your slot only after PhonePe confirms the payment.</p><div className="upi-details"><span>Amount payable</span><strong>{formatMoney(phonePePayment?.amount)}</strong><span>PhonePe order</span><b>{phonePePayment?.merchantOrderId}</b></div><a className="primary full" href={phonePePayment?.redirectUrl}>Open PhonePe UAT checkout <ArrowRight size={18}/></a><button className="secondary full" disabled={paying} onClick={checkPhonePeStatus}>{paying ? 'Checking payment…' : 'I completed payment — check status'}</button><button className="link" onClick={() => setPaymentStep(null)}>Close and pay later</button></>}</section></div>}{message && <p className="inline-notice">{message}</p>}</section>;
}

function PhonePePaymentHub() {
  const [bookings, setBookings] = useState([]);
  const [checkout, setCheckout] = useState(null);
  const [paying, setPaying] = useState(false);
  const [message, setMessage] = useState('');
  const load = () => api('/api/booking/my').then((result) => setBookings(result.data.filter((booking) => booking.status === 'pending' && booking.payment_status !== 'paid'))).catch((error) => setMessage(error.message));
  useEffect(() => { load(); }, []);
  const startPhonePe = async (booking) => {
    try {
      setPaying(true);
      const result = await api(`/api/phonepe/booking/${booking.booking_id}/initiate`, { method:'POST', body:'{}' });
      const payment = { ...booking, ...result.data };
      setCheckout(payment);
      localStorage.setItem('smartpark_phonepe_payment', JSON.stringify(payment));
    } catch (error) { setMessage(error.message); } finally { setPaying(false); }
  };
  const checkStatus = async () => {
    if (!checkout?.merchantOrderId) return;
    try {
      setPaying(true);
      const result = await api(`/api/phonepe/order/${checkout.merchantOrderId}/status`);
      if (result.data.state === 'COMPLETED') {
        localStorage.removeItem('smartpark_phonepe_payment');
        setCheckout(null);
        setMessage('PhonePe payment completed. Your slot is reserved and the PDF receipt is now available in My Bookings.');
        load();
      } else setMessage(`PhonePe payment is ${result.data.state.toLowerCase()}. Complete it on PhonePe, then check again.`);
    } catch (error) { setMessage(error.message); } finally { setPaying(false); }
  };
  return <section className="panel"><div className="panel-title"><div><span className="eyebrow">PHONEPE UAT</span><h2>Secure UPI checkout</h2><p>Pay the required booking advance through PhonePe’s sandbox checkout.</p></div><button className="secondary" onClick={load}>Refresh</button></div>{checkout ? <div className="qr-payment"><h3>Pay {formatMoney(checkout.amount)} for Booking #{checkout.booking_id}</h3><p>PhonePe provides the QR, UPI ID and app options on its secure checkout.</p><a className="primary full" href={checkout.redirectUrl}>Open PhonePe UAT checkout <ArrowRight size={18}/></a><button className="secondary full" disabled={paying} onClick={checkStatus}>{paying ? 'Checking payment…' : 'I completed payment — check status'}</button><button className="link" onClick={() => setCheckout(null)}>Close and pay later</button></div> : bookings.length ? <div className="history-list">{bookings.map((booking) => <article key={booking.booking_id}><div><b>Booking #{booking.booking_id} · Slot P-{String(booking.slot_number).padStart(2, '0')}</b><span>{new Date(booking.expected_arrival).toLocaleString('en-IN')} · {formatMoney(booking.amount_paid)}</span></div><button className="primary" disabled={paying} onClick={() => startPhonePe(booking)}>Pay with PhonePe</button></article>)}</div> : <p className="empty-copy">No unpaid bookings.</p>}{message && <p className="inline-notice">{message}</p>}</section>;
}

function RazorpayBookingSuccess({ booking, onDone }) { return <section className="panel booking-confirm booking-success"><CheckCircle2/><span className="eyebrow">PAYMENT SUCCESSFUL</span><h2>Slot P-{String(booking.slot_number).padStart(2, '0')} is reserved.</h2><div className="booking-code">SMARTPARK <b>#{booking.booking_id}</b></div><p><CalendarDays size={17}/> {new Date(booking.expected_arrival).toLocaleString('en-IN')}</p><p><Clock3 size={17}/> {booking.duration_hours} hour(s) · {formatMoney(booking.amount)}</p><p><CreditCard size={17}/> Payment complete · Razorpay</p><a className="secondary full" href={`/api/booking/${booking.booking_id}/payment-receipt`} target="_blank" rel="noreferrer">Download payment receipt (PDF)</a><button className="primary full" onClick={onDone}>Go to My Bookings</button></section>; }

function RazorpayAdvanceBookingPanel({ user, slots, setPage }) {
  const [selected, setSelected] = useState(null);
  const [arrival, setArrival] = useState(() => localDateTime());
  const [duration, setDuration] = useState(1);
  const [fastag, setFastag] = useState(null);
  const [confirmation, setConfirmation] = useState(null);
  const [paymentStep, setPaymentStep] = useState(null);
  const [createdBooking, setCreatedBooking] = useState(null);
  const [paying, setPaying] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => { api('/api/fastag/me').then((result) => setFastag(result.data)).catch(() => setFastag(null)); }, []);
  const createBooking = async () => {
    if (createdBooking) return createdBooking;
    if (!selected) throw new Error('Select a free parking slot first.');
    const result = await api('/api/booking', { method:'POST', body:JSON.stringify({ slotNumber:selected.slot_id, expectedArrival:new Date(arrival).toISOString(), durationHours:Number(duration), vehicleNumber:user.vehicle_number }) });
    const booking = { booking_id:result.data.booking_id, slot_number:selected.slot_id, expected_arrival:arrival, duration_hours:Number(duration), amount:result.data.amount, payment_status:'unpaid' };
    setCreatedBooking(booking);
    return booking;
  };
  const confirmRazorpayPayment = async (booking, payment) => {
    try {
      setPaying(true);
      await api('/api/payment/verify', { method:'POST', body:JSON.stringify({ bookingId:booking.booking_id, amount:booking.amount, razorpayPaymentId:payment.razorpay_payment_id, razorpayOrderId:payment.razorpay_order_id, razorpaySignature:payment.razorpay_signature, mode:'razorpay' }) });
      setCreatedBooking(null);
      setPaymentStep(null);
      setConfirmation({ ...booking, payment_status:'paid' });
    } catch (error) { setMessage(error.message); } finally { setPaying(false); }
  };
  const startRazorpay = async () => {
    try {
      setPaying(true);
      const booking = await createBooking();
      const order = await api('/api/payment/order', { method:'POST', body:JSON.stringify({ bookingId:booking.booking_id, amount:booking.amount }) });
      if (order.data.demo) throw new Error('Razorpay is not configured. Add your Live Key ID and Live Key Secret to backend/.env, then restart npm run dev.');
      if (!(await loadRazorpay())) throw new Error('Unable to load Razorpay checkout. Check your internet connection.');
      new window.Razorpay({ key:order.data.key, amount:order.data.amount, currency:'INR', name:'SmartPark', description:`Booking #${booking.booking_id} · Slot P-${String(booking.slot_number).padStart(2, '0')}`, order_id:order.data.id, prefill:{ name:user.name, email:user.email, contact:user.phone }, theme:{ color:'#1B3A6B' }, handler:(payment) => confirmRazorpayPayment(booking, payment), modal:{ ondismiss:() => setMessage('Razorpay checkout closed. Your booking is still unpaid; you can pay it later from Payments.') } }).open();
    } catch (error) { setMessage(error.message); } finally { setPaying(false); }
  };
  const payFastag = async () => {
    try {
      setPaying(true);
      const booking = await createBooking();
      await api(`/api/fastag/pay/booking/${booking.booking_id}`, { method:'POST', body:'{}' });
      setCreatedBooking(null);
      setPaymentStep(null);
      setConfirmation({ ...booking, payment_status:'paid' });
    } catch (error) { setMessage(error.message); } finally { setPaying(false); }
  };

  if (confirmation) return <RazorpayBookingSuccess booking={confirmation} onDone={() => setPage('bookings')}/>;
  return <section className="book-layout"><div className="panel intro-panel"><span className="eyebrow">ONLINE PRE-BOOKING</span><h2>Reserve from one to twelve hours.</h2><p>Every pre-booking requires a mandatory, non-refundable online advance of <b>Rs.20</b> for the first hour. Physical payment is not available for reservations.</p><div className="legend"><span><i className="free"/>Free</span><span><i className="occupied"/>Occupied</span><span><i className="reserved"/>Reserved</span></div></div><div className="panel"><SlotMap slots={slots} selectable={user.status !== 'blocked'} selected={selected} onSelect={setSelected}/></div>{selected && <div className="booking-panel panel"><span className="eyebrow">CONFIRM AND PAY</span><h3>Slot P-{String(selected.slot_id).padStart(2, '0')}</h3><label>Expected arrival<input type="datetime-local" min={localDateTime()} max={localDateTime(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000))} value={arrival} onChange={(event) => setArrival(event.target.value)}/></label><label>Reserved duration <b>{duration} hour{duration > 1 ? 's' : ''}</b><input type="range" min="1" max="12" value={duration} onChange={(event) => setDuration(event.target.value)}/></label><div className="advance-summary"><b>Mandatory non-refundable online advance</b><strong>Rs. 20</strong><span>Covers the first hour. Your selected reservation duration is {duration} hour{duration > 1 ? 's' : ''}.</span></div><button className="primary full" onClick={() => { setMessage(''); setPaymentStep('choice'); }}>Pay Rs. 20 advance online <CreditCard size={18}/></button></div>}{paymentStep && <div className="payment-modal-backdrop"><section className="payment-modal panel"><button className="modal-close" aria-label="Close payment" onClick={() => setPaymentStep(null)}><X/></button><span className="eyebrow">CHOOSE PAYMENT METHOD</span><h2>Pay Rs.20 advance</h2><p>Select a secure online payment option to reserve your slot.</p><button className="payment-method fastag-method" disabled={!fastag || paying} onClick={payFastag}><b>FASTag payment</b><span>{fastag ? `Auto-deduct Rs.20 from wallet · Balance ${formatMoney(fastag.wallet_balance)}` : 'Link an active FASTag in Payments to use this option'}</span></button><button className="payment-method upi-method" disabled={paying} onClick={startRazorpay}><b>Razorpay payment</b><span>UPI, QR, cards, net banking and supported wallets</span></button></section></div>}{message && <p className="inline-notice">{message}</p>}</section>;
}

function RazorpayPaymentHub() {
  const [bookings, setBookings] = useState([]);
  const [paying, setPaying] = useState(false);
  const [message, setMessage] = useState('');
  const load = () => api('/api/booking/my').then((result) => setBookings(result.data.filter((booking) => booking.status === 'pending' && booking.payment_status !== 'paid'))).catch((error) => setMessage(error.message));
  useEffect(() => { load(); }, []);
  const startRazorpay = async (booking) => {
    try {
      setPaying(true);
      const order = await api('/api/payment/order', { method:'POST', body:JSON.stringify({ bookingId:booking.booking_id, amount:booking.amount_paid }) });
      if (order.data.demo) throw new Error('Razorpay is not configured. Add your Live Key ID and Live Key Secret to backend/.env, then restart npm run dev.');
      if (!(await loadRazorpay())) throw new Error('Unable to load Razorpay checkout. Check your internet connection.');
      new window.Razorpay({ key:order.data.key, amount:order.data.amount, currency:'INR', name:'SmartPark', description:`Booking #${booking.booking_id} · Slot P-${String(booking.slot_number).padStart(2, '0')}`, order_id:order.data.id, theme:{ color:'#1B3A6B' }, handler:async (payment) => { try { await api('/api/payment/verify', { method:'POST', body:JSON.stringify({ bookingId:booking.booking_id, amount:booking.amount_paid, razorpayPaymentId:payment.razorpay_payment_id, razorpayOrderId:payment.razorpay_order_id, razorpaySignature:payment.razorpay_signature, mode:'razorpay' }) }); setMessage('Razorpay payment completed. Your slot is reserved and the PDF receipt is available in My Bookings.'); load(); } catch (error) { setMessage(error.message); } }, modal:{ ondismiss:() => setMessage('Razorpay checkout closed. You can pay later.') } }).open();
    } catch (error) { setMessage(error.message); } finally { setPaying(false); }
  };
  return <section className="panel"><div className="panel-title"><div><span className="eyebrow">RAZORPAY</span><h2>Secure online checkout</h2><p>Pay booking advances by UPI, QR, card, net banking, or wallet.</p></div><button className="secondary" onClick={load}>Refresh</button></div>{bookings.length ? <div className="history-list">{bookings.map((booking) => <article key={booking.booking_id}><div><b>Booking #{booking.booking_id} · Slot P-{String(booking.slot_number).padStart(2, '0')}</b><span>{new Date(booking.expected_arrival).toLocaleString('en-IN')} · {formatMoney(booking.amount_paid)}</span></div><button className="primary" disabled={paying} onClick={() => startRazorpay(booking)}>Pay with Razorpay</button></article>)}</div> : <p className="empty-copy">No unpaid bookings.</p>}{message && <p className="inline-notice">{message}</p>}</section>;
}

function ThemeButton({ dark, toggle }) { return <button className="icon-button" aria-label="Toggle dark mode" onClick={toggle}>{dark ? <Sun size={18}/> : <Moon size={18}/>}</button>; }
function Brand() { return <div className="brand"><span className="brand-icon"><ParkingSquare size={22}/></span><span>Smart<span>Park</span></span></div>; }

function Landing({ slots, openAuth, openAvailability }) { const free = slots.filter((slot) => slot.status === 'free').length; return <><header className="landing-header"><Brand/><nav><a href="#features">Features</a><a href="#pricing">Pricing</a><button className="text-button" onClick={() => openAuth('login')}>Log in</button><button className="primary small" onClick={() => openAuth('register')}>Get started</button></nav></header><main className="landing"><section className="hero"><div className="hero-copy"><span className="eyebrow">RFID-POWERED PARKING</span><h1>Smart parking,<br/><em>zero hassle.</em></h1><p>Book a space in seconds, enter with RFID, and receive automated billing straight to your phone.</p><div className="hero-actions"><button className="primary" onClick={() => openAuth('login')}>Book a slot <ArrowRight size={18}/></button><button className="secondary" onClick={openAvailability}>View live availability</button></div><div className="hero-proof"><span><CheckCircle2 size={17}/> 6 secure RFID slots</span><span><CheckCircle2 size={17}/> Instant receipts</span></div></div><div className="hero-panel"><div className="panel-glow"/><div className="availability-card"><span className="live-pill"><i/> LIVE AVAILABILITY</span><h3><b>{free}</b> of 6 slots free</h3><SlotMap slots={slots} /><p><Clock3 size={15}/> Updated just now</p></div></div></section><section id="features" className="feature-section"><div><span className="eyebrow">DESIGNED FOR EASE</span><h2>Every part of parking,<br/>thought through.</h2></div><div className="features">{[[ShieldCheck,'RFID Entry','A touchless, secure way in and out.'],[CalendarDays,'Web Booking','Reserve a space before you leave.'],[CircleDollarSign,'Auto Billing','Fair, simple pricing calculated automatically.'],[BarChart3,'Live Dashboard','See every slot and session in real time.']].map(([Icon,title,text]) => <article key={title}><Icon/><h3>{title}</h3><p>{text}</p></article>)}</div></section><section id="pricing" className="pricing"><div><span className="eyebrow">SIMPLE PRICING</span><h2>No surprise fees.</h2></div><div className="price-list"><div><span>Normal parking</span><b>Rs.20<small>/hour</small></b></div><div><span>Overtime</span><b>Rs.40<small>/hour</small></b></div><div><span>Monthly pass</span><b>Contact admin</b></div></div></section></main><footer>© 2026 SmartPark &nbsp; · &nbsp; Built for safer, simpler parking.</footer></> }

function Auth({ mode, close, onLogin }) {
  const [registerStep, setRegisterStep] = useState(1);
  const [view, setView] = useState('main');
  const [resetSent, setResetSent] = useState(false);
  const [loginVerificationToken, setLoginVerificationToken] = useState('');
  const [form, setForm] = useState({ name:'', email:'', phone:'', password:'', confirmPassword:'', code:'', emailOtp:'', vehicleNumber:'', vehicleType:'car' });
  const [message, setMessage] = useState('');
  const update = (event) => setForm({ ...form, [event.target.name]:event.target.value });
  const submit = async (event) => {
    event.preventDefault();
    setMessage('');
    try {
      if (view === 'loginOtp') {
        const result = await api('/api/auth/login/verify', { method:'POST', body:JSON.stringify({ loginVerificationToken, emailOtp:form.emailOtp }) });
        return onLogin(result.data);
      }
      if (view === 'forgot') {
        if (!resetSent) {
          await api('/api/auth/password-reset/request', { method:'POST', body:JSON.stringify({ email:form.email }) });
          setResetSent(true);
          return setMessage('OTP sent. Check your email.');
        }
        await api('/api/auth/password-reset/confirm', { method:'POST', body:JSON.stringify({ email:form.email, code:form.code, newPassword:form.password, confirmPassword:form.confirmPassword }) });
        setView('main');
        setResetSent(false);
        return setMessage('Password reset. You can now log in.');
      }
      if (mode === 'register' && registerStep < 3) return setRegisterStep(registerStep + 1);
      const result = await api(mode === 'login' ? '/api/auth/login' : '/api/auth/register', { method:'POST', body:JSON.stringify(form) });
      if (result.data.requiresLoginVerification) {
        setLoginVerificationToken(result.data.loginVerificationToken);
        setView('loginOtp');
        return setMessage(`OTP sent to ${result.data.email}.`);
      }
      onLogin(result.data);
    } catch (error) { setMessage(error.message); }
  };
  const fields = view === 'loginOtp' ? <><label>Email OTP<input required name="emailOtp" inputMode="numeric" maxLength="6" value={form.emailOtp} onChange={update}/></label><button type="button" className="link" onClick={async () => { try { const result = await api('/api/auth/login/resend', { method:'POST', body:JSON.stringify({ loginVerificationToken }) }); setMessage(result.message); } catch (error) { setMessage(error.message); } }}>Resend email OTP</button></> : view === 'forgot' ? <>{!resetSent ? <label>Email<input required name="email" type="email" value={form.email} onChange={update}/></label> : <><label>Email<input required name="email" type="email" value={form.email} onChange={update}/></label><label>OTP<input required name="code" inputMode="numeric" maxLength="6" value={form.code} onChange={update}/></label><label>New password<input required minLength="8" name="password" type="password" value={form.password} onChange={update}/></label><label>Confirm password<input required minLength="8" name="confirmPassword" type="password" value={form.confirmPassword} onChange={update}/></label></>}</> : mode === 'login' ? <><label>Email<input required name="email" type="email" value={form.email} onChange={update}/></label><label>Password<input required name="password" type="password" value={form.password} onChange={update}/></label><div className="form-row"><label className="checkbox"><input type="checkbox"/> Remember me</label><button type="button" className="link" onClick={() => { setView('forgot'); setMessage(''); }}>Forgot password?</button></div></> : registerStep === 1 ? <><label>Full name<input required name="name" value={form.name} onChange={update}/></label><label>Email address<input required name="email" type="email" value={form.email} onChange={update}/></label><label>Phone number<input required name="phone" value={form.phone} onChange={update}/></label><label>Create password<input required minLength="8" name="password" type="password" value={form.password} onChange={update}/></label><label>Confirm password<input required minLength="8" name="confirmPassword" type="password" value={form.confirmPassword} onChange={update}/></label></> : registerStep === 2 ? <><label>Vehicle number<input required name="vehicleNumber" placeholder="MH 12 AB 1234" value={form.vehicleNumber} onChange={update}/></label><label>Vehicle type<select name="vehicleType" value={form.vehicleType} onChange={update}><option>car</option><option>bike</option><option>other</option></select></label></> : <div className="success-upload"><span><UserRound size={28}/></span><h3>Profile photo</h3><p>Optional — you can add this later from your profile.</p></div>;
  const title = view === 'loginOtp' ? 'Verify your login.' : view === 'forgot' ? (resetSent ? 'Set a new password.' : 'Reset your password.') : mode === 'login' ? 'Park smarter today.' : ['A few details first.','Tell us about your vehicle.','Almost done!'][registerStep - 1];
  return <div className="auth-shell"><button className="modal-close" onClick={() => close(null)}><X/></button><form className="auth-card" onSubmit={submit}><Brand/><span className="eyebrow">{view === 'loginOtp' ? 'TWO-STEP VERIFICATION' : view === 'forgot' ? 'ACCOUNT RECOVERY' : mode === 'login' ? 'WELCOME BACK' : `CREATE ACCOUNT · STEP ${registerStep}/3`}</span><h2>{title}</h2>{message && <p className="form-error">{message}</p>}{fields}<button className="primary full" type="submit">{view === 'loginOtp' ? 'Verify and log in' : view === 'forgot' ? (resetSent ? 'Reset password' : 'Send OTP') : mode === 'login' ? 'Log in' : registerStep === 3 ? 'Create account' : 'Continue'} <ChevronRight size={18}/></button>{(view === 'forgot' || view === 'loginOtp') ? <p className="switch-auth"><button type="button" className="link" onClick={() => { setView('main'); setResetSent(false); setMessage(''); }}>Back to login</button></p> : <p className="switch-auth">{mode === 'login' ? 'New to SmartPark?' : 'Already have an account?'} <button type="button" className="link" onClick={() => { setRegisterStep(1); mode === 'login' ? close('register') : close('login'); }}>{mode === 'login' ? 'Create account' : 'Log in'}</button></p>}<p className="demo">Demo: <b>admin@smartpark.local</b> / <b>admin123</b></p></form></div>;
}

function Shell({ user, page, setPage, logout, dark, toggleDark, children }) { const items = user.role === 'admin' ? ADMIN_NAV : NAV; return <div className="app-shell"><aside><Brand/><div className="user-mini"><span>{user.name?.[0]}</span><div><b>{user.name}</b><small>{user.role === 'admin' ? 'Administrator' : 'Parking member'}</small></div></div><nav>{items.map(({id,label,icon:Icon}) => <button key={id} className={page === id ? 'active' : ''} onClick={() => setPage(id)}><Icon size={19}/>{label}</button>)}</nav><div className="sidebar-bottom"><ThemeButton dark={dark} toggle={toggleDark}/><button onClick={logout}><LogOut size={18}/>Sign out</button></div></aside><main className="app-main"><header className="dashboard-header"><div><span className="eyebrow">{user.role === 'admin' ? 'OPERATIONS CENTER' : 'YOUR PARKING'}</span><h1>{page === 'overview' ? `Good ${new Date().getHours() < 12 ? 'morning' : 'afternoon'}, ${user.name?.split(' ')[0]}.` : items.find((item) => item.id === page)?.label}</h1></div><div className="header-actions"><ThemeButton dark={dark} toggle={toggleDark}/><NotificationsPanel/><span className="avatar">{user.name?.[0]}</span></div></header>{children}</main><nav className="mobile-nav">{items.slice(0,5).map(({id,label,icon:Icon}) => <button key={id} className={page === id ? 'active' : ''} onClick={() => setPage(id)}><Icon size={19}/><span>{label.replace('My ','')}</span></button>)}</nav></div>; }

function ActiveSessionCard({ user }) { const [session, setSession] = useState(null); const [now, setNow] = useState(Date.now()); useEffect(() => { api('/api/sessions/active').then((result) => setSession(result.data[0] || null)).catch(() => setSession(null)); const timer = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(timer); }, []); if (!session) return null; const elapsed = Math.max(0, Math.floor((now - new Date(session.entry_time).getTime()) / 1000)); const scaledHours = elapsed / 5; const overtime = scaledHours > Number(session.registered_hours); const bill = user.pass_type === 'monthly' ? 0 : Number(session.registered_hours) * 20 + Math.max(0, Math.ceil(scaledHours - Number(session.registered_hours))) * 40; return <section className={`active-session ${overtime ? 'overtime' : ''}`}><div><span className="eyebrow">ACTIVE PARKING</span><h2>You are parked at Slot P-{String(session.slot_number).padStart(2,'0')}</h2><p>Entered {new Date(session.entry_time).toLocaleTimeString('en-IN', { hour:'2-digit', minute:'2-digit' })} · Registered for {session.registered_hours} hour(s)</p></div><div className="active-metrics"><span><small>Elapsed</small><b>{Math.floor(scaledHours)}h {Math.floor((scaledHours % 1) * 60)}m</b></span><span><small>Current bill</small><b>{formatMoney(bill)}</b></span><strong>{overtime ? 'OVERTIME' : 'ON TIME'}</strong></div></section>; }

function NotificationsPanel() { const [open, setOpen] = useState(false); const [notifications, setNotifications] = useState([]); const unread = notifications.filter((item) => !item.is_read).length; const load = () => api('/api/notifications').then((result) => setNotifications(result.data)).catch(() => {}); useEffect(() => { void load(); }, []); const markRead = async () => { await api('/api/notifications/read', { method:'PUT' }); load(); }; return <div className="notifications"><button className="icon-button bell" onClick={() => { setOpen(!open); if (!open) load(); }}><Bell size={19}/>{unread > 0 && <i/>}</button>{open && <div className="notification-menu"><div><b>Notifications</b><button className="link" onClick={markRead}>Mark all read</button></div>{notifications.length ? notifications.slice(0, 6).map((item) => <article key={item.notif_id} className={item.is_read ? '' : 'unread'}><b>{item.type.replace('_', ' ')}</b><p>{item.message}</p><small>{new Date(item.created_at).toLocaleString('en-IN')}</small></article>) : <p className="empty-copy">You are all caught up.</p>}</div>}</div>; }

function AdminSlotsPanel({ slots, onGate }) { const [notice, setNotice] = useState(''); const updateSlot = async (slot, action) => { try { const result = action === 'release' ? await api(`/api/slots/${slot.slot_id}/release`, { method:'POST' }) : await api(`/api/slots/${slot.slot_id}/maintenance`, { method:'PUT', body:JSON.stringify({ enabled: action === 'maintenance' }) }); setNotice(result.message); } catch (error) { setNotice(error.message); } }; return <section className="panel admin-slot-panel"><div className="panel-title"><div><span className="eyebrow">ADMIN CONTROLS</span><h2>Slot control center</h2><p>Operate gates, force-release a slot, or take it out of service.</p></div></div><div className="slot-control-list">{slots.map((slot) => <article key={slot.slot_id}><div><b>{slot.label || `Slot P-${String(slot.slot_id).padStart(2,'0')}`}</b><span className={`table-status ${slot.status}`}>{slot.status}</span></div><div className="slot-controls"><button className="secondary" onClick={() => onGate(slot, slot.gate_status === 'open' ? 'close' : 'open')}>{slot.gate_status === 'open' ? 'Close gate' : 'Open gate'}</button>{slot.status === 'occupied' && <button className="secondary" onClick={() => updateSlot(slot, 'release')}>Force release</button>}<button className="secondary" onClick={() => updateSlot(slot, slot.status === 'maintenance' ? 'active' : 'maintenance')}>{slot.status === 'maintenance' ? 'Restore slot' : 'Maintenance'}</button></div></article>)}</div>{notice && <p className="inline-notice"><CheckCircle2 size={16}/>{notice}</p>}</section>; }

function HardwarePanel() { const [status, setStatus] = useState(null); const [events, setEvents] = useState([]); const load = () => { api('/api/hardware/status').then((result) => setStatus(result.data)).catch(() => {}); api('/api/hardware/events').then((result) => setEvents(result.data)).catch(() => {}); }; useEffect(() => { load(); const timer = setInterval(load, 5000); return () => clearInterval(timer); }, []); return <section className="hardware-grid"><div className="panel hardware-status"><span className={`hardware-dot ${status?.connected ? 'online' : 'offline'}`}/><div><span className="eyebrow">RASPBERRY PI GPIO</span><h2>{status?.connected ? 'Hardware connected' : 'Waiting for hardware heartbeat'}</h2><p>{status?.lastHeartbeat ? `Last heartbeat: ${new Date(status.lastHeartbeat).toLocaleString('en-IN')}` : 'Send a heartbeat from the Pi to establish connection.'}</p></div></div><div className="panel"><div className="panel-title"><h3>Latest Pi events</h3><button className="link" onClick={load}>Refresh</button></div><div className="event-log">{events.length ? events.map((event) => <article key={event.event_id}><span>{event.event_type}</span><b>Slot {event.slot_number || '—'}</b><small>{new Date(event.created_at).toLocaleString('en-IN')}</small></article>) : <p className="empty-copy">No hardware events received yet.</p>}</div></div></section>; }

function HistoryPanel({ type }) { const [items, setItems] = useState([]); const [loading, setLoading] = useState(true); const [message, setMessage] = useState(''); const load = () => { setLoading(true); const endpoint = type === 'sessions' ? '/api/sessions/user/me' : '/api/booking/my'; api(endpoint).then((result) => setItems(result.data)).catch((error) => setMessage(error.message)).finally(() => setLoading(false)); }; useEffect(() => { load(); }, [type]); const isSession = type === 'sessions'; const cancelBooking = async (booking) => { if (!window.confirm(`Cancel booking #${booking.booking_id}?`)) return; try { await api(`/api/booking/${booking.booking_id}/cancel`, { method:'PUT' }); setMessage('Booking cancelled.'); load(); } catch (error) { setMessage(error.message); } }; const rescheduleBooking = async (booking) => { const current = new Date(booking.expected_arrival).toISOString().slice(0, 16); const value = window.prompt('New arrival time (YYYY-MM-DDTHH:MM)', current); if (!value) return; const expectedArrival = new Date(value); if (Number.isNaN(expectedArrival.getTime())) return setMessage('Enter a valid date and time.'); try { await api(`/api/booking/${booking.booking_id}`, { method:'PUT', body:JSON.stringify({ expectedArrival:expectedArrival.toISOString() }) }); setMessage('Booking rescheduled.'); load(); } catch (error) { setMessage(error.message); } }; const payBooking = async (booking) => { try { const order = await api('/api/payment/order', { method:'POST', body:JSON.stringify({ bookingId:booking.booking_id, amount:booking.amount_paid }) }); if (order.data.demo) { await api('/api/payment/verify', { method:'POST', body:JSON.stringify({ bookingId:booking.booking_id, amount:booking.amount_paid, razorpayPaymentId:`demo_${Date.now()}`, mode:'online' }) }); setMessage('Demo payment completed.'); return load(); } if (!(await loadRazorpay())) throw new Error('Unable to open Razorpay checkout'); new window.Razorpay({ key:order.data.key, amount:order.data.amount, currency:'INR', name:'Smart Parking System', description:`Slot P-${String(booking.slot_number).padStart(2,'0')} booking`, order_id:order.data.id, theme:{color:'#1B3A6B'}, handler:async (payment) => { try { await api('/api/payment/verify', { method:'POST', body:JSON.stringify({ bookingId:booking.booking_id, amount:booking.amount_paid, razorpayPaymentId:payment.razorpay_payment_id, razorpayOrderId:payment.razorpay_order_id, razorpaySignature:payment.razorpay_signature, mode:'online' }) }); setMessage('Payment completed.'); load(); } catch (error) { setMessage(error.message); } } }).open(); } catch (error) { setMessage(error.message); } }; const calendarLink = (booking) => `data:text/calendar;charset=utf-8,${encodeURIComponent(`BEGIN:VCALENDAR\nVERSION:2.0\nBEGIN:VEVENT\nUID:smartpark-${booking.booking_id}\nDTSTART:${new Date(booking.expected_arrival).toISOString().replace(/[-:]/g, '').replace('.000', '')}\nDTEND:${new Date(new Date(booking.expected_arrival).getTime() + Number(booking.duration_hours) * 3600000).toISOString().replace(/[-:]/g, '').replace('.000', '')}\nSUMMARY:SmartPark Slot P-${String(booking.slot_number).padStart(2, '0')}\nEND:VEVENT\nEND:VCALENDAR`)}`; return <section className="panel history-panel"><div className="panel-title"><div><span className="eyebrow">YOUR RECORDS</span><h2>{isSession ? 'Parking history' : 'My bookings'}</h2><p>{isSession ? 'Download receipts and review every completed parking session.' : 'Manage your upcoming and previous parking reservations.'}</p></div><button className="secondary" onClick={load}>Refresh</button></div>{loading ? <div className="history-empty">Loading your records…</div> : items.length ? <div className="history-list">{items.map((item) => <article key={isSession ? item.session_id : item.booking_id}><div><b>{isSession ? `Session #${item.session_id}` : `Booking #${item.booking_id}`}</b><span>{isSession ? `Slot P-${String(item.slot_number).padStart(2,'0')} · ${new Date(item.entry_time).toLocaleString('en-IN')}` : `Slot P-${String(item.slot_number).padStart(2,'0')} · ${new Date(item.expected_arrival).toLocaleString('en-IN')}`}</span></div><div><strong>{isSession ? formatMoney(item.total_amount) : formatMoney(item.amount_paid)}</strong><small>{isSession ? (item.exit_time ? 'Completed' : 'Active') : `${item.status} · ${item.payment_status}`}</small></div>{isSession ? (item.exit_time ? <a className="link" href={`/api/sessions/${item.session_id}/receipt`} target="_blank" rel="noreferrer">Download PDF</a> : <span className="receipt-pending">Available after exit</span>) : <div className="booking-actions"><a className="link" href={`/api/booking/${item.booking_id}/confirmation`} target="_blank" rel="noreferrer">PDF</a>{item.status === 'pending' && <><a className="link" href={calendarLink(item)} download={`smartpark-booking-${item.booking_id}.ics`}>Calendar</a>{item.payment_status !== 'paid' && <button className="link" onClick={() => payBooking(item)}>Pay</button>}<button className="link" onClick={() => rescheduleBooking(item)}>Reschedule</button><button className="link danger-link" onClick={() => cancelBooking(item)}>Cancel</button></>}</div>}</article>)}</div> : <div className="history-empty"><ParkingSquare size={32}/><b>{isSession ? 'No parking sessions yet' : 'No bookings yet'}</b><p>Your completed activity will appear here.</p></div>}{message && <p className="inline-notice">{message}</p>}</section>; }

function ProfilePanel({ user }) {
  const [form, setForm] = useState({ name:user.name || '', phone:user.phone || '', vehicleNumber:user.vehicle_number || '', vehicleColor:user.vehicle_color || '' });
  const [message, setMessage] = useState('');
  const [verificationCode, setVerificationCode] = useState('');
  const [verified, setVerified] = useState(Boolean(user.email_verified_at));
  const save = async (event) => { event.preventDefault(); try { await api('/api/auth/profile', { method:'PUT', body:JSON.stringify(form) }); setMessage('Profile saved successfully.'); } catch (error) { setMessage(error.message); } };
  const sendVerification = async () => { try { const result = await api('/api/auth/email-verification/send', { method:'POST', body:'{}' }); setMessage(result.message); } catch (error) { setMessage(error.message); } };
  const confirmVerification = async () => { try { await api('/api/auth/email-verification/confirm', { method:'POST', body:JSON.stringify({ code:verificationCode }) }); setVerified(true); setVerificationCode(''); setMessage('Email verified successfully.'); } catch (error) { setMessage(error.message); } };
  return <section className="profile-grid"><div className="panel profile-card"><span className="profile-avatar">{user.name?.[0]}</span><h2>{user.name}</h2><p>{user.email}</p><span className={`pass-badge ${user.rfid_uid ? '' : 'pending'}`}>{user.rfid_uid ? `RFID ${user.rfid_uid} active` : 'RFID card pending assignment'}</span><span className="pass-badge">{user.pass_type === 'monthly' ? 'Monthly pass' : 'Normal parking'}</span>{verified ? <span className="pass-badge">Email verified</span> : <div><button type="button" className="link" onClick={sendVerification}>Send email OTP</button><label>Email OTP<input value={verificationCode} inputMode="numeric" maxLength="6" onChange={(event) => setVerificationCode(event.target.value)}/></label><button type="button" className="secondary" onClick={confirmVerification}>Verify email</button></div>}</div><form className="panel profile-form" onSubmit={save}><h3>Personal details</h3><label>Full name<input value={form.name} onChange={(event) => setForm({...form, name:event.target.value})}/></label><label>Email<input value={user.email} disabled/></label><label>Phone number<input value={form.phone} onChange={(event) => setForm({...form, phone:event.target.value})}/></label><label>Vehicle number<input value={form.vehicleNumber} onChange={(event) => setForm({...form, vehicleNumber:event.target.value})}/></label><label>Vehicle colour<input value={form.vehicleColor} onChange={(event) => setForm({...form, vehicleColor:event.target.value})}/></label><button className="primary">Save changes</button>{message && <p className="inline-notice">{message}</p>}</form></section>;
}

function PaymentHub({ user }) {
  const [fastag, setFastag] = useState(null); const [bookings, setBookings] = useState([]); const [payments, setPayments] = useState([]); const [refunds, setRefunds] = useState([]); const [tagNumber, setTagNumber] = useState(''); const [vehicleNumber, setVehicleNumber] = useState(user.vehicle_number || ''); const [qr, setQr] = useState(null); const [message, setMessage] = useState('');
  const load = () => Promise.all([api('/api/fastag/me'), api('/api/booking/my'), api('/api/payment/history'), api('/api/refunds/me')]).then(([tag, bookingData, paymentData, refundData]) => { setFastag(tag.data); setBookings(bookingData.data); setPayments(paymentData.data); setRefunds(refundData.data); }).catch((error) => setMessage(error.message));
  useEffect(() => { void load(); }, []);
  const linkFastag = async (event) => { event.preventDefault(); try { const result = await api('/api/fastag/link', { method:'POST', body:JSON.stringify({ tagNumber, vehicleNumber }) }); setFastag(result.data); setMessage(result.message); } catch (error) { setMessage(error.message); } };
  const topUp = async () => { const amount = window.prompt('Demo FASTag wallet top-up amount (Rs.50 to Rs.5,000)', '500'); if (!amount) return; try { const result = await api('/api/fastag/top-up', { method:'POST', body:JSON.stringify({ amount:Number(amount) }) }); setFastag(result.data); setMessage(result.message); } catch (error) { setMessage(error.message); } };
  const generateQr = async (booking) => { try { const result = await api(`/api/payment/qr/booking/${booking.booking_id}`, { method:'POST', body:'{}' }); setQr(result.data); setMessage(result.message); } catch (error) { setMessage(error.message); } };
  const confirmQr = async () => { try { await api('/api/payment/verify', { method:'POST', body:JSON.stringify({ bookingId:qr.bookingId, amount:qr.amount, razorpayPaymentId:`demo_qr_${Date.now()}`, mode:'upi_qr' }) }); setQr(null); setMessage('UPI QR payment completed and slot reserved.'); load(); } catch (error) { setMessage(error.message); } };
  const payFastag = async (booking) => { try { const result = await api(`/api/fastag/pay/booking/${booking.booking_id}`, { method:'POST', body:'{}' }); setMessage(result.message); load(); } catch (error) { setMessage(error.message); } };
  const requestRefund = async (payment) => { const reason = window.prompt('Why do you need a refund?'); if (!reason) return; try { const result = await api('/api/refunds/request', { method:'POST', body:JSON.stringify({ paymentId:payment.payment_id, reason }) }); setMessage(result.message); load(); } catch (error) { setMessage(error.message); } };
  const pending = bookings.filter((booking) => booking.status === 'pending' && booking.payment_status !== 'paid');
  return <section className="payment-hub"><div className="panel"><div className="panel-title"><div><span className="eyebrow">PAYMENT CENTRE</span><h2>QR and FASTag payments</h2><p>FASTag uses a secure SmartPark demo wallet until a bank partner is connected.</p></div><button className="secondary" onClick={load}>Refresh</button></div>{fastag ? <div className="fastag-card"><b>{fastag.provider_name}</b><span>Tag {fastag.tag_number} · {fastag.vehicle_number}</span><strong>{formatMoney(fastag.wallet_balance)}</strong><small>{fastag.status} demo wallet balance</small><button className="secondary" onClick={topUp}>Top up demo wallet</button></div> : <form className="profile-form compact-form" onSubmit={linkFastag}><h3>Link FASTag</h3><label>FASTag ID<input required value={tagNumber} onChange={(event) => setTagNumber(event.target.value)} placeholder="TAG123456"/></label><label>Vehicle number<input required value={vehicleNumber} onChange={(event) => setVehicleNumber(event.target.value.toUpperCase())} placeholder="MH 12 AB 1234"/></label><button className="primary">Link demo FASTag</button></form>}</div><div className="panel"><h3>Unpaid bookings</h3>{pending.length ? pending.map((booking) => <div className="payment-row" key={booking.booking_id}><div><b>Booking #{booking.booking_id} · Slot P-{String(booking.slot_number).padStart(2,'0')}</b><span>{new Date(booking.expected_arrival).toLocaleString('en-IN')} · {formatMoney(booking.amount_paid)}</span></div><div><button className="secondary" onClick={() => generateQr(booking)}>UPI QR</button><button className="primary" disabled={!fastag} onClick={() => payFastag(booking)}>Pay FASTag</button></div></div>) : <p className="empty-copy">No unpaid bookings.</p>}</div>{qr && <div className="panel qr-payment"><span className="eyebrow">UPI QR PAYMENT</span><h3>Pay {formatMoney(qr.amount)} for Booking #{qr.bookingId}</h3><img src={qr.qrDataUrl} alt="UPI payment QR code"/><b>{qr.upiId}</b><a className="secondary" href={qr.upiUrl}>Open payment app</a><button className="primary" onClick={confirmQr}>I completed demo UPI payment</button><button className="link" onClick={() => setQr(null)}>Close</button></div>}<div className="panel"><h3>Refunds</h3>{payments.filter((payment) => payment.status === 'success').map((payment) => <div className="payment-row" key={payment.payment_id}><div><b>{formatMoney(payment.amount)} · {payment.payment_mode}</b><span>Payment #{payment.payment_id} · {new Date(payment.payment_time).toLocaleString('en-IN')}</span></div><button className="link" onClick={() => requestRefund(payment)}>Request refund</button></div>)}{refunds.length ? <div className="refund-list">{refunds.map((refund) => <small key={refund.refund_id}>Refund #{refund.refund_id}: {refund.status} · {formatMoney(refund.amount)}</small>)}</div> : null}</div>{message && <p className="inline-notice">{message}</p>}</section>;
}

function AdminBookingsPanel() { const [bookings, setBookings] = useState([]); const [message, setMessage] = useState(''); const load = () => api('/api/booking/admin/all').then((result) => setBookings(result.data)).catch((error) => setMessage(error.message)); useEffect(() => { void load(); }, []); return <section className="panel history-panel"><div className="panel-title"><div><span className="eyebrow">ADMIN BOOKINGS</span><h2>All reservations</h2><p>Review every user booking and its payment status.</p></div><button className="secondary" onClick={load}>Refresh</button></div>{bookings.length ? <div className="history-list">{bookings.map((booking) => <article key={booking.booking_id}><div><b>Booking #{booking.booking_id} · Slot P-{String(booking.slot_number).padStart(2, '0')}</b><span>{booking.name} · {booking.email} · {new Date(booking.expected_arrival).toLocaleString('en-IN')}</span></div><div><strong>{formatMoney(booking.amount_paid)}</strong><small>{booking.status} · {booking.payment_status}</small></div><div className="booking-actions">{booking.payment_status === 'paid' ? <a className="link" href={`/api/booking/${booking.booking_id}/payment-receipt`} target="_blank" rel="noreferrer">Payment PDF</a> : <span className="receipt-pending">Payment pending</span>}</div></article>)}</div> : <div className="history-empty"><b>No bookings yet</b><p>Completed user reservations appear here.</p></div>}{message && <p className="inline-notice">{message}</p>}</section>; }

function AdminPaymentsPanel() { const [payments, setPayments] = useState([]); const [message, setMessage] = useState(''); const load = () => api('/api/payments/admin/all').then((result) => setPayments(result.data)).catch((error) => setMessage(error.message)); useEffect(() => { void load(); }, []); return <section className="panel history-panel"><div className="panel-title"><div><span className="eyebrow">ADMIN PAYMENTS</span><h2>Payment ledger</h2><p>All successful and recorded payments from SmartPark users.</p></div><button className="secondary" onClick={load}>Refresh</button></div>{payments.length ? <div className="history-list">{payments.map((payment) => <article key={payment.payment_id}><div><b>Payment #{payment.payment_id}{payment.booking_id ? ` · Booking #${payment.booking_id}` : ''}</b><span>{payment.name} · {payment.email}{payment.slot_number ? ` · Slot P-${String(payment.slot_number).padStart(2, '0')}` : ''}</span></div><div><strong>{formatMoney(payment.amount)}</strong><small>{payment.payment_mode || 'online'} · {payment.status} · {new Date(payment.payment_time).toLocaleString('en-IN')}</small></div><div className="booking-actions"><span className="receipt-pending">{payment.razorpay_id ? `Razorpay: ${payment.razorpay_id}` : 'Recorded payment'}</span></div></article>)}</div> : <div className="history-empty"><b>No payments yet</b><p>Verified payments will appear here.</p></div>}{message && <p className="inline-notice">{message}</p>}</section>; }

function AdminRefunds() {
  const [refunds, setRefunds] = useState([]); const [message, setMessage] = useState('');
  const load = () => api('/api/refunds/admin').then((result) => setRefunds(result.data)).catch((error) => setMessage(error.message));
  useEffect(() => { void load(); }, []);
  const update = async (refund, action) => { const note = window.prompt(`Optional note for refund #${refund.refund_id}`) || ''; try { const result = await api(`/api/refunds/${refund.refund_id}`, { method:'PUT', body:JSON.stringify({ action, note }) }); setMessage(result.message); load(); } catch (error) { setMessage(error.message); } };
  return <section className="panel history-panel"><div className="panel-title"><div><span className="eyebrow">ADMIN PAYMENT CONTROL</span><h2>Refund queue</h2><p>Approve, reject, or process customer refunds.</p></div><button className="secondary" onClick={load}>Refresh</button></div>{refunds.length ? <div className="history-list">{refunds.map((refund) => <article key={refund.refund_id}><div><b>Refund #{refund.refund_id} · {refund.name}</b><span>{refund.email} · {refund.payment_mode} · {refund.reason}</span></div><div><strong>{formatMoney(refund.amount)}</strong><small>{refund.status}</small></div><div className="booking-actions">{refund.status === 'requested' && <><button className="link" onClick={() => update(refund, 'approve')}>Approve</button><button className="link danger-link" onClick={() => update(refund, 'reject')}>Reject</button></>}{refund.status === 'approved' && <button className="link" onClick={() => update(refund, 'process')}>Process</button>}</div></article>)}</div> : <p className="empty-copy">No refund requests.</p>}{message && <p className="inline-notice">{message}</p>}</section>;
}

function SettingsPanel() { const [rates, setRates] = useState({ normalRate:20, overtimeRate:40, peakRate:30, peakStart:'18:00', peakEnd:'21:00' }); const [message, setMessage] = useState(''); useEffect(() => { api('/api/rates').then((result) => setRates({ normalRate:result.data.normal_rate, overtimeRate:result.data.overtime_rate, peakRate:result.data.peak_rate, peakStart:result.data.peak_start?.slice(0,5) || '', peakEnd:result.data.peak_end?.slice(0,5) || '' })).catch(() => {}); }, []); const save = async (event) => { event.preventDefault(); try { await api('/api/rates', { method:'PUT', body:JSON.stringify(rates) }); setMessage('Rates saved. Future billing uses the new values.'); } catch (error) { setMessage(error.message); } }; return <section className="settings-grid"><form className="panel profile-form" onSubmit={save}><h3>Parking rates</h3><label>Normal rate (Rs./hr)<input value={rates.normalRate} type="number" onChange={(event) => setRates({...rates, normalRate:event.target.value})}/></label><label>Overtime rate (Rs./hr)<input value={rates.overtimeRate} type="number" onChange={(event) => setRates({...rates, overtimeRate:event.target.value})}/></label><label>Peak rate (Rs./hr)<input value={rates.peakRate} type="number" onChange={(event) => setRates({...rates, peakRate:event.target.value})}/></label><label>Peak start<input value={rates.peakStart} type="time" onChange={(event) => setRates({...rates, peakStart:event.target.value})}/></label><label>Peak end<input value={rates.peakEnd} type="time" onChange={(event) => setRates({...rates, peakEnd:event.target.value})}/></label><button className="primary">Save rates</button>{message && <p className="inline-notice">{message}</p>}</form><div className="panel"><h3>System status</h3><p className="status-line"><i/> MySQL database <b>Connected</b></p><p className="status-line"><i/> Pi hardware endpoint <b>Protected</b></p><p className="status-line"><i/> Demo time scale <b>5 seconds / hour</b></p></div></section>; }

function AdminUsersPanel() { const [users, setUsers] = useState([]); const [message, setMessage] = useState(''); const load = () => api('/api/users').then((result) => setUsers(result.data)).catch((error) => setMessage(error.message)); useEffect(() => { void load(); }, []); const block = async (user) => { try { await api(`/api/users/${user.user_id}/block`, { method:'PUT', body:JSON.stringify({ blocked:user.status !== 'blocked' }) }); setMessage(`${user.name} updated.`); load(); } catch (error) { setMessage(error.message); } }; const assign = async (user) => { const rfidUid = window.prompt(`RFID UID for ${user.name}`); if (!rfidUid) return; try { await api(`/api/users/${user.user_id}/rfid`, { method:'PUT', body:JSON.stringify({ rfidUid }) }); setMessage(`RFID assigned to ${user.name}.`); load(); } catch (error) { setMessage(error.message); } }; return <section className="panel history-panel"><div className="panel-title"><div><span className="eyebrow">ADMINISTRATION</span><h2>User management</h2><p>Assign cards, activate pending accounts, and block access.</p></div><button className="secondary" onClick={load}>Refresh</button></div><div className="history-list">{users.map((user) => <article key={user.user_id}><div><b>{user.name}</b><span>{user.email} · {user.vehicle_number || 'No vehicle'}</span></div><div><strong>{user.pass_type}</strong><small>{user.rfid_uid ? 'RFID active' : 'RFID pending'} · {user.status}</small></div><div className="slot-controls">{!user.rfid_uid && <button className="secondary" onClick={() => assign(user)}>Assign RFID</button>}<button className="secondary" onClick={() => block(user)}>{user.status === 'blocked' ? 'Unblock' : 'Block'}</button></div></article>)}</div>{message && <p className="inline-notice">{message}</p>}</section>; }

function Dashboard({ user, slots, page, setPage, admin }) { const [selected, setSelected] = useState(null); const [duration, setDuration] = useState(2); const [arrival, setArrival] = useState(() => localDateTime()); const [paymentMode, setPaymentMode] = useState('online'); const [pendingPayment, setPendingPayment] = useState(null); const [confirmation, setConfirmation] = useState(null); const [paying, setPaying] = useState(false); const [toast, setToast] = useState(''); const gate = async (slot, action) => { try { await api('/api/gate', { method:'POST', body:JSON.stringify({ slot:slot.slot_id, action }) }); setToast(`Gate command sent to P-${String(slot.slot_id).padStart(2,'0')}`); } catch (error) { setToast(error.message); } }; const finishPayment = async (booking, payment) => { try { setPaying(true); await api('/api/payment/verify', { method:'POST', body:JSON.stringify({ bookingId:booking.booking_id, amount:booking.amount, razorpayPaymentId:payment?.razorpay_payment_id || `demo_upi_${Date.now()}`, razorpayOrderId:payment?.razorpay_order_id, razorpaySignature:payment?.razorpay_signature, mode:'online' }) }); setPendingPayment(null); setConfirmation({...booking, payment_status:'paid'}); } catch (error) { setToast(error.message); } finally { setPaying(false); } }; const createBooking = async () => { try { if (paymentMode === 'cash') return setToast('Choose demo UPI payment to reserve this slot now.'); const result = await api('/api/booking', { method:'POST', body:JSON.stringify({ slotNumber:selected.slot_id, expectedArrival:new Date(arrival).toISOString(), durationHours:Number(duration), vehicleNumber:user.vehicle_number }) }); const booking = { booking_id:result.data.booking_id, slot_number:selected.slot_id, expected_arrival:arrival, duration_hours:Number(duration), amount:result.data.amount, payment_status:result.data.payment_status }; if (result.data.amount === 0) return setConfirmation(booking); const order = await api('/api/payment/order', { method:'POST', body:JSON.stringify({ bookingId:booking.booking_id, amount:booking.amount }) }); if (order.data.demo) return setPendingPayment(booking); if (!(await loadRazorpay())) throw new Error('Unable to open Razorpay checkout'); new window.Razorpay({ key:order.data.key, amount:order.data.amount, currency:'INR', name:'Smart Parking System', description:`Slot P-${String(booking.slot_number).padStart(2,'0')} booking`, order_id:order.data.id, prefill:{name:user.name,email:user.email,contact:user.phone}, theme:{color:'#1B3A6B'}, handler:(payment) => finishPayment(booking, payment), modal:{ondismiss:() => setToast('Payment cancelled. You can pay later from My Bookings.')} }).open(); } catch (error) { setToast(error.message); } };
  const free = slots.filter((slot) => slot.status === 'free').length;
  if (page === 'book') return <RazorpayAdvanceBookingPanel user={user} slots={slots} setPage={setPage}/>;
  if (page === 'book' && confirmation) return <BookingPaymentSuccess booking={confirmation} onDone={() => { setConfirmation(null); setSelected(null); setPage('bookings'); }}/>;
  if (page === 'book' && pendingPayment) return <DemoUpiPayment booking={pendingPayment} paying={paying} onPay={() => finishPayment(pendingPayment)} onCancel={async () => { try { await api(`/api/booking/${pendingPayment.booking_id}/cancel`, { method:'PUT' }); setPendingPayment(null); setToast('Payment cancelled. Your booking is not reserved.'); } catch (error) { setToast(error.message); } }}/>;
  if (page === 'book') return confirmation ? <section className="panel booking-confirm booking-success"><CheckCircle2/><span className="eyebrow">BOOKING CONFIRMED</span><h2>Slot P-{String(confirmation.slot_number).padStart(2,'0')} is reserved.</h2><div className="booking-code">SMARTPARK <b>#{confirmation.booking_id}</b></div><p><CalendarDays size={17}/> {new Date(confirmation.expected_arrival).toLocaleString('en-IN')}</p><p><Clock3 size={17}/> {confirmation.duration_hours} hour(s) · {formatMoney(confirmation.amount)}</p><p><CreditCard size={17}/> {confirmation.payment_status === 'paid' ? 'Paid online' : 'Pay at exit'}</p><a className="secondary full" href={`/api/booking/${confirmation.booking_id}/confirmation`} target="_blank" rel="noreferrer">Download booking receipt (PDF)</a><button className="primary full" onClick={() => { setConfirmation(null); setSelected(null); setPage('bookings'); }}>Go to My Bookings</button></section> : <section className="book-layout"><div className="panel intro-panel"><span className="eyebrow">STEP 1 OF 3</span><h2>Choose your perfect spot.</h2><p>{user.status === 'blocked' ? 'Your account is blocked from making reservations. Please contact parking support.' : user.rfid_uid ? 'Free spaces are shown in teal. Pick one to continue with a secure booking.' : 'You can reserve a slot now. RFID assignment is required only before using the physical gate.'}</p><div className="legend"><span><i className="free"/>Free</span><span><i className="occupied"/>Occupied</span><span><i className="reserved"/>Reserved</span></div></div><div className="panel"><SlotMap slots={slots} selectable={user.status !== 'blocked'} selected={selected} onSelect={setSelected}/></div>{selected && <div className="booking-panel panel"><span className="eyebrow">STEP 2 OF 3</span><h3>P-{String(selected.slot_id).padStart(2,'0')} is yours.</h3><label>Expected arrival<input type="datetime-local" min={localDateTime()} max={localDateTime(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000))} value={arrival} onChange={(event) => setArrival(event.target.value)}/></label><label>Duration <b>{duration} hour{duration > 1 ? 's' : ''} · {formatMoney(duration * 20)}</b><input type="range" min="1" max="12" value={duration} onChange={(event) => setDuration(event.target.value)}/></label><div className="payment-choice"><b>Payment method</b><label><input type="radio" checked={paymentMode === 'online'} onChange={() => setPaymentMode('online')}/> Pay online (UPI, card, net banking)</label><label><input type="radio" checked={paymentMode === 'cash'} onChange={() => setPaymentMode('cash')}/> Pay at physical exit</label></div><button className="primary full" onClick={createBooking}>{paymentMode === 'online' ? `Pay ${formatMoney(duration * 20)}` : 'Confirm booking'} <CreditCard size={18}/></button></div>}</section>;
  if (page === 'sessions') return <HistoryPanel type="sessions"/>;
  if (admin && page === 'bookings') return <AdminBookingsPanel/>;
  if (admin && page === 'payments') return <AdminPaymentsPanel/>;
  if (page === 'bookings') return <HistoryPanel type="bookings"/>;
  if (page === 'payments') return <><RazorpayPaymentHub/><PaymentHub user={user}/></>;
  if (page === 'profile') return <ProfilePanel user={user}/>;
  if (admin && page === 'users') return <AdminUsersPanel/>;
  if (admin && page === 'slots') return <AdminSlotsPanel slots={slots} onGate={gate}/>;
  if (admin && page === 'hardware') return <HardwarePanel/>;
  if (admin && page === 'refunds') return <AdminRefunds/>;
  if (admin && page === 'analytics') return <Analytics/>;
  if (admin && page === 'settings') return <SettingsPanel/>;
  const stats = admin ? [{label:'Occupied now',value:`${6-free}/6`,icon:Car,color:'red'},{label:'Revenue today',value:'Rs. 1,480',icon:CircleDollarSign,color:'teal'},{label:'Active sessions',value:'02',icon:Clock3,color:'amber'},{label:'Registered users',value:'128',icon:Users,color:'blue'}] : [{label:'Available slots',value:`${free}/6`,icon:ParkingSquare,color:'teal'},{label:'Active parking',value:'P-02',icon:Car,color:'blue'},{label:'Current bill',value:'Rs. 40',icon:CircleDollarSign,color:'amber'},{label:'Total visits',value:'14',icon:Clock3,color:'red'}];
  return <section>{!admin && <ActiveSessionCard user={user}/>}<div className="stat-grid">{stats.map(({label,value,icon:Icon,color}) => <article className="stat-card" key={label}><span className={color}><Icon size={21}/></span><div><small>{label}</small><b>{value}</b></div></article>)}</div><div className="dashboard-grid"><div className="panel live-panel"><div className="panel-title"><div><span className="eyebrow">REAL-TIME</span><h2>Live parking map</h2></div><span className="live-pill"><i/> LIVE</span></div><LiveParkingMap slots={slots} admin={admin} onGate={gate}/></div><div className="panel activity"><div className="panel-title"><h3>Recent activity</h3><button className="link">View all</button></div>{[['entry','Rahul entered P-02','Just now'],['exit','Priya completed P-04','12 min ago'],['booking','New booking for P-03','25 min ago'],['release','P-01 auto-released','1 hr ago']].map(([type,text,time]) => <div className="activity-item" key={text}><span className={type}>{type === 'entry' ? '↘' : type === 'exit' ? '↗' : '·'}</span><p>{text}<small>{time}</small></p></div>)}</div></div>{toast && <button className="toast" onClick={() => setToast('')}><CheckCircle2 size={18}/>{toast}<X size={16}/></button>}</section>;
}

function DataTable({ title, data, columns }) { return <section className="panel table-panel"><div className="panel-title"><div><h2>{title}</h2><p>Review and manage your complete parking activity.</p></div><label className="search"><Search size={17}/><input placeholder="Search records"/></label></div><div className="table-wrap"><table><thead><tr>{columns.map((column) => <th key={column}>{column}</th>)}<th>Action</th></tr></thead><tbody>{data.map((row, index) => <tr key={row.id || row.name || index}>{columns.map((column) => { const key = column.toLowerCase().replaceAll(' ','_'); const value = row[key] ?? row[column.toLowerCase()] ?? row[column] ?? (column === 'Slot' ? `P-${String(row.slot).padStart(2,'0')}` : '—'); return <td key={column}>{column === 'Status' ? <span className="table-status">{value}</span> : column === 'Amount' ? formatMoney(value) : value}</td>; })}<td><button className="link">View</button></td></tr>)}</tbody></table></div></section> }
function Analytics() { const [report, setReport] = useState({ summary:{ revenue:0, sessions:0, average_bill:0 }, chart:[] }); useEffect(() => { api('/api/reports/weekly').then((result) => setReport(result.data)).catch(() => {}); }, []); const data = report.chart.map((row) => ({ day:new Date(row.date).toLocaleDateString('en-IN', { weekday:'short' }), revenue:Number(row.revenue), sessions:Number(row.sessions) })); return <section className="analytics"><div className="panel chart-panel"><div className="panel-title"><div><span className="eyebrow">WEEKLY REVENUE</span><h2>{formatMoney(report.summary.revenue)}</h2></div><span className="trend">{report.summary.sessions} sessions</span></div><ResponsiveContainer width="100%" height={260}><AreaChart data={data}><defs><linearGradient id="revenue" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#0d9488" stopOpacity=".32"/><stop offset="100%" stopColor="#0d9488" stopOpacity="0"/></linearGradient></defs><XAxis dataKey="day" axisLine={false} tickLine={false}/><Tooltip formatter={(value) => formatMoney(value)}/><Area type="monotone" dataKey="revenue" stroke="#0d9488" strokeWidth={3} fill="url(#revenue)"/></AreaChart></ResponsiveContainer></div><div className="panel"><h3>Live report</h3><p className="insight"><b>{report.summary.sessions} parking sessions</b> recorded in the selected weekly period.</p><p className="insight"><b>{formatMoney(report.summary.average_bill)}</b> is the average completed bill.</p><p className="insight"><b>{formatMoney(report.summary.revenue)}</b> is total collected revenue.</p></div></section> }

export default function App() { const [user, setUser] = useState(null); const [page, setPage] = useState('overview'); const [slots, setSlots] = useState(INITIAL_SLOTS); const [authMode, setAuthMode] = useState(null); const [dark, setDark] = useState(() => localStorage.getItem('smartpark_theme') === 'dark'); useEffect(() => { document.documentElement.dataset.theme = dark ? 'dark' : 'light'; localStorage.setItem('smartpark_theme', dark ? 'dark' : 'light'); }, [dark]); useEffect(() => { api('/api/auth/me').then((result) => setUser(result.data)).catch(() => setUser(null)); api('/api/slots').then((result) => setSlots(result.data)).catch(() => {}); const socket = io(API_BASE_URL || undefined, { withCredentials: !API_BASE_URL, auth: accessToken() ? { token:accessToken() } : undefined }); socket.on('allSlots', ({slots:updated}) => setSlots(updated)); socket.on('heartbeatSync', ({slots:updated}) => setSlots(updated)); socket.on('slotUpdate', (update) => setSlots((current) => current.map((slot) => slot.slot_id === update.slot ? {...slot,...update} : slot))); socket.on('slotStatusChange', (update) => setSlots((current) => current.map((slot) => slot.slot_id === update.slot ? {...slot,...update} : slot))); socket.on('billTick', (update) => setSlots((current) => current.map((slot) => slot.slot_id === update.slot ? {...slot, live_bill:update.current_bill, is_overtime:update.is_overtime, elapsed_minutes:update.elapsed_minutes} : slot))); return () => socket.close(); }, []); const loggedIn = ({ user: signedInUser, accessToken: token }) => { if (token) sessionStorage.setItem('smartpark_access_token', token); setUser(signedInUser); setAuthMode(null); }; const logout = async () => { await api('/api/auth/logout', { method:'POST' }).catch(() => {}); sessionStorage.removeItem('smartpark_access_token'); setUser(null); setPage('overview'); }; return <><AnimatePresence mode="wait">{user ? <motion.div key="app" initial={{opacity:0}} animate={{opacity:1}}><Shell user={user} page={page} setPage={setPage} logout={logout} dark={dark} toggleDark={() => setDark(!dark)}><Dashboard user={user} slots={slots} page={page} setPage={setPage} admin={user.role === 'admin'}/></Shell></motion.div> : <motion.div key="landing" initial={{opacity:0}} animate={{opacity:1}}><Landing slots={slots} openAuth={setAuthMode} openAvailability={() => document.querySelector('.hero-panel')?.scrollIntoView({behavior:'smooth'})}/></motion.div>}</AnimatePresence>{authMode && <Auth mode={authMode} close={setAuthMode} onLogin={loggedIn}/>}</> }
